 async function load(){try{const r=await fetch('monsters-book-2024.json?v=2.6');if(!r.ok)throw Error('Catálogo não carregou.');const d=await r.json();const seen=new Set();catalog=(d.monsters||[]).map(m=>normalizeMonster(m)).filter(m=>{if(seen.has(m.id))throw Error('ID repetido no catálogo.');seen.add(m.id);return true;});coverage=d.coverage||'';render?.();}catch(e){console.warn(e);notify('Catálogo indisponível; personalizados e referências dos backups continuam acessíveis.');}}
