 function actionCards(m,key,title){const arr=m[key];if(!arr.length)return '';const i=instance(detailInstanceId);return `<h3 class="dm-section-title">${title}</h3>${arr.map((a,n)=>{const id=actionToken(key,a,n),used=i?.uses[id]||0,waiting=i?.recharge[id],disabled=i&&(a.maxUses&&used>=a.maxUses||waiting||key==='legendaryActions'&&m.legendaryBudget&&i.legendaryUsed+a.legendaryCost>m.legendaryBudget);const attrs=`data-mid="${html(m.id)}" data-list="${key}" data-index="${n}" data-instance="${html(detailInstanceId)}"`;return `<article class="dm-power"><div><b>${html(a.name)}</b><span class="mini-label"> · ${TYPES[a.kind]} ${a.kind==='attack'?sgn(a.attackBonus):a.dc?'CD '+a.dc+' '+html(a.saveAbility.toUpperCase()):''}</span><p>${html(a.description)}</p><small>${html(a.damageParts.length?a.damageParts.map(p=>p.formula+' '+p.type).join(' + '):a.formula||'Sem rolagem de dano')}${a.maxUses?' · '+used+'/'+a.maxUses+' usados':''}${a.rechargeMin?' · Recarga '+a.rechargeMin+'–6'+(waiting?' pendente':' pronta'):''}${key==='legendaryActions'?' · custo '+a.legendaryCost:''}</small></div><div class="dm-power-buttons">${button(a.kind==='attack'?'Acerto':a.kind==='damage'||a.kind==='heal'?'Rolar e registrar':'Registrar uso','action',attrs+(disabled?' disabled':''),'small')}${a.kind==='attack'||a.kind==='save'?a.formula||a.damageParts.length?button(a.kind==='heal'?'Cura':'Dano','damage',attrs,'small primary')+(a.kind==='attack'?button('Crítico','damage',attrs+' data-critical="true"','small ghost'):''): '':''}${i&&a.maxUses?button('Restaurar 1 uso','restore-use',attrs+(used?'':' disabled'),'small ghost'):''}${i&&a.rechargeMin?button('Rolar recarga','recharge',attrs+(waiting?'':' disabled'),'small ghost'):''}</div></article>`;}).join('')}`;}
 function details(m){if(m.pending)return `<div class="rule-notice"><h2>${html(m.name)}</h2><p>${html(m.source)} · p. ${html(m.page)} (PDF ${m.pdfPage}).</p><p>Esta referência foi identificada no livro, mas seu bloco ainda requer conferência. Números não legíveis não são utilizados em encontros.</p><p>${html(m.notes)}</p></div>`;const i=instance(detailInstanceId);return `<div class="dm-statblock">${portraitHtml(m)}<div class="dm-stat-title"><h2>${html(i?.name||m.name)}</h2><p>${html(m.size)} · ${html(m.type)} · ${html(m.alignment)}</p><small>${html(m.source)}${m.page?' · p. '+html(m.page):''}${m.pdfPage?' (PDF '+m.pdfPage+')':''}</small></div>${m.provisional?'<p class="rule-notice"><b>Extração automática — confira no livro.</b> Este bloco ainda não foi conferido visualmente. Ações, fórmulas e bônus podem estar incompletos; use a página indicada ou crie uma cópia corrigida.</p>':''}<div class="dm-keyfacts"><span>CA <b>${m.ac}</b></span><span>PV <b>${i?i.hp+'/'+i.maxHp:m.hp}</b> ${html(m.hpFormula)}</span><span>Iniciativa <b>${sgn(m.initiative)}</b></span><span>ND <b>${html(m.cr)}</b></span></div><p class="dm-small">Deslocamento: ${html(m.speed)}</p>${modeSelect('detail')}<div class="dm-abilities">${rollAttrs(m)}</div><p>Salvaguardas: ${Object.entries(m.saves).map(([k,v])=>html(k.toUpperCase())+' '+sgn(v)).join(' · ')||'Modificadores dos atributos'}</p><div>${Object.entries(m.skills).map(([k,v])=>button(html(k)+' '+sgn(v),'roll',`data-kind="skill" data-skill="${html(k)}" data-mid="${html(m.id)}"`,'small ghost')).join('')}</div><p>${html(m.senses)}</p><p>${html(m.defenses)}</p>${m.traits.map(t=>`<p class="dm-trait"><b>${html(t.name)}.</b> ${html(t.description)}</p>`).join('')}${i?`<p class="hint">Usos pertencem a esta cópia. Rolar Dano/Crítico não desconta novamente o uso registrado no acerto. Ações, alvos e recargas são confirmados pela mesa.</p>`:'<p class="hint">Rolagens avulsas do catálogo não consomem recursos de um encontro.</p>'}${m.resources.map(r=>{const used=i?.uses['resource:'+r.id]||0;return `<div class="dm-resource"><b>${html(r.name)}</b><span>${Math.max(0,r.max-used)}/${r.max} restantes</span><p>${html(r.description)}</p>${i?button('Gastar 1','resource',`data-id="${html(i.id)}" data-resource="${html(r.id)}" ${used>=r.max?'disabled':''}`,'small')+button('Restaurar 1','resource',`data-id="${html(i.id)}" data-resource="${html(r.id)}" data-restore="true" ${used?'':'disabled'}`,'small ghost'):''}</div>`;}).join('')}${m.legendaryBudget?`<div class="rule-notice">Ações lendárias: ${Math.max(0,m.legendaryBudget-(i?.legendaryUsed||0))}/${m.legendaryBudget}. ${i?button('Renovar reserva','legendary-reset',`data-id="${html(i.id)}"`,'small ghost'):''} A mesa determina quando renovar.</div>`:''}${GROUPS.map(([key,title])=>actionCards(m,key,title)).join('')}<p class="reading">${html(m.notes)}</p></div>`;}
