 function actionEditor(a,n,key){const p=`dm-a-${key}-${n}`;return `<fieldset class="dm-edit-action"><legend>${html(a.name||'Nova ação')}</legend>${button('Excluir','action-delete',`data-list="${key}" data-index="${n}"`,'small ghost')}<div class="dm-form-cols">${field('Nome',p+'-name',input(p+'-name',a.name))}${field('Tipo',p+'-kind',select(p+'-kind',KINDS.map(k=>[k,TYPES[k]]),a.kind,'Tipo da ação'))}${field('Bônus de ataque',p+'-hit',input(p+'-hit',a.attackBonus,'number'))}${field('Fórmula (ex.: 2d10+5d6+4)',p+'-formula',input(p+'-formula',a.formula,'text','placeholder="2d10+5d6+4"'))}${field('Tipo de dano',p+'-type',typeSelect022(p+'-type',a.damageType))}${field('CD',p+'-dc',input(p+'-dc',a.dc,'number'))}${field('Salvaguarda',p+'-save',select(p+'-save',[['','Nenhuma'],...ATTRS],a.saveAbility,'Atributo da salvaguarda'))}${field('Usos (0 = ilimitado)',p+'-uses',input(p+'-uses',a.maxUses,'number','min="0"'))}${field('Recarga no d6 (0 = sem recarga)',p+'-recharge',input(p+'-recharge',a.rechargeMin,'number','min="0" max="6"'))}${field('Custo lendário',p+'-cost',input(p+'-cost',a.legendaryCost,'number','min="1"'))}</div>${(()=>{a._rows=a._rows||partsToRows022(a.damageParts);const rows=a._rows;return `<div class="dm-dmg-rows"><div class="dm-dmg-head"><b>Dano por partes</b><span class="hint">${rows.length?'Estas linhas valem no lugar da fórmula acima.':'Opcional: monte o dano com dados e números fixos, cada um com o seu tipo.'}</span></div>${rows.map((r,k)=>`<div class="dm-dmg-row"><input id="${p}-r${k}-q" type="number" min="-99" max="99" value="${html(r.qtd)}" aria-label="${r.dado==='fixo'?'Número fixo':'Quantidade de dados'}"><select id="${p}-r${k}-d" aria-label="Dado">${[...DICE.map(d=>[d,d]),['fixo','número fixo']].map(([v,l])=>`<option value="${v}" ${v===r.dado?'selected':''}>${l}</option>`).join('')}</select>${typeSelect022(p+'-r'+k+'-t',r.tipo)}${button('✕','part-del',`data-list="${key}" data-index="${n}" data-row="${k}" aria-label="Tirar esta parte"`,'small ghost')}</div>`).join('')}<div class="flex">${button('+ Dado de dano','part-add',`data-list="${key}" data-index="${n}" data-mode="dice"`,'small')}${button('+ Número fixo','part-add',`data-list="${key}" data-index="${n}" data-mode="fixed"`,'small')}</div>${rows.length?`<p class="hint">Total: <b>${html(rowsToParts022(rows).map(x=>x.formula+(x.type?' '+x.type:'')).join(' + ')||'—')}</b></p>`:''}</div>`;})()}${field('Descrição',p+'-desc',`<textarea id="${p}-desc">${html(a.description)}</textarea>`)}</fieldset>`;}
 function editorHtml(){const m=editor;return `<div class="dm-editor"><p class="hint">${m.fromScratch?'Só o nome é obrigatório. Se deixar <strong>PV máximos</strong> vazio, ele é calculado pelos <strong>Dados de vida</strong> (ex.: 4d10+8 = 30). Em cada ação escolha o tipo (Ataque, Salvaguarda, Dano, Cura ou Habilidade) e a fórmula de dados (ex.: 2d6+3); os botões de rolagem aparecem na ficha do monstro.':'Alterações do livro são salvas em cópias próprias. Todas as listas de ações podem ser editadas aqui.'}</p>${m.needsReview?'<label><input id="dm-e-reviewed" type="checkbox"> Conferi os valores e ações na página indicada do livro.</label><p>'+html(m.notes)+'</p>':''}<div class="dm-form-cols">${[['Nome','name'],['Tipo','type'],['Tamanho','size'],['Alinhamento','alignment'],['ND','cr'],['CA','ac','number'],['PV máximos','hp','number'],['Dados de vida','hpFormula'],['Iniciativa','initiative','number'],['Deslocamento','speed'],['Reserva lendária','legendaryBudget','number'],['Bônus de proficiência','profBonus','number']].map(([l,k,t])=>field(l,'dm-e-'+k,input('dm-e-'+k,k==='profBonus'?pbOf022(m):m[k],t||'text',k==='profBonus'?'min="0" max="20" title="Começa pelo ND; mude se quiser"':''))).join('')}</div><h3>Atributos</h3><div class="dm-form-cols">${ATTRS.map(([k,l])=>field(l,'dm-e-'+k,input('dm-e-'+k,m.abilities[k],'number','min="1" max="30"'))).join('')}</div>${(()=>{const pb=pbOf022(m),def=k=>mod(Number(m.abilities[k])||10)+pb,ab=k=>ATTRS.find(x=>x[0]===k)?.[1].slice(0,3).toUpperCase();const row=(kind,i,label,k,has,v)=>`<label class="dm-prof"><input type="checkbox" class="dm-prof-check" id="dm-${kind}-${i}-c" data-key="${k}" data-target="dm-${kind}-${i}" ${has?'checked':''}><span>${html(label)} <small>${ab(k)}</small></span><input type="number" id="dm-${kind}-${i}" min="-20" max="40" value="${has?html(v):''}" placeholder="${sgn(def(k))}" aria-label="Bônus de ${html(label)}"></label>`;return `<h3>Salvaguardas</h3><p class="hint">Marque as proficientes: o bônus é o modificador do atributo + o <b>Bônus de proficiência</b> (campo acima, +${pb}). Dá para mudar cada número.</p><div class="dm-prof-grid">${ATTRS.map(([k,l],i)=>row('sv',i,l,k,m.saves[k]!=null,m.saves[k])).join('')}</div><h3>Perícias</h3><p class="hint">Marque as perícias do monstro. Para especialização, escreva o valor maior.</p><div class="dm-prof-grid">${SKILLS.map(([n,k],i)=>row('sk',i,n,k,m.skills[n]!=null,m.skills[n])).join('')}</div>`;})()}${[['Sentidos','senses',m.senses],['Defesas','defenses',m.defenses],['Traços (nome: descrição)','traits',m.traits.map(t=>t.name+': '+t.description).join('\n')],['Recursos (nome: máximo; uma linha por recurso)','resources',m.resources.map(r=>r.name+': '+r.max).join('\n')],['Anotações','notes',m.notes]].map(([l,k,v])=>field(l,'dm-e-'+k,`<textarea id="dm-e-${k}" rows="3">${html(v)}</textarea>`)).join('')}${GROUPS.map(([key,title])=>`<h3 class="dm-section-title">${title}</h3>${m[key].map((a,i)=>actionEditor(a,i,key)).join('')}${button('Adicionar '+title.toLowerCase(),'action-add',`data-list="${key}"`,'ghost small')}`).join('')}</div>`;}
 const get=id=>document.getElementById(id)?.value;
 const lines=v=>String(v||'').split('\n').map(v=>v.trim()).filter(Boolean);
 const pairs=v=>Object.fromEntries(lines(v).map(l=>{const i=l.lastIndexOf(':');return [l.slice(0,i).trim(),Number(l.slice(i+1))];}).filter(([k,v])=>k&&Number.isFinite(v)));
 function readEditor(){if(!editor)return;for(const k of ['name','type','size','alignment','cr','ac','hp','hpFormula','initiative','speed','legendaryBudget','profBonus','senses','defenses','notes'])editor[k]=get('dm-e-'+k)??editor[k];for(const [k]of ATTRS)editor.abilities[k]=get('dm-e-'+k)??editor.abilities[k];{const pb=pbOf022(editor),val=(kind,i,k)=>{const el=document.getElementById(`dm-${kind}-${i}-c`);if(!el)return undefined;if(!el.checked)return null;const n=Number(get(`dm-${kind}-${i}`));return get(`dm-${kind}-${i}`)!==''&&Number.isFinite(n)?Math.round(n):mod(Number(editor.abilities[k])||10)+pb;};
  if(document.getElementById('dm-sv-0-c')){const sv={};ATTRS.forEach(([k],i)=>{const v=val('sv',i,k);if(v!=null)sv[k]=v;});editor.saves=sv;}
  if(document.getElementById('dm-sk-0-c')){const known=new Set(SKILLS.map(x=>x[0]));const sk=Object.fromEntries(Object.entries(editor.skills||{}).filter(([n])=>!known.has(n)));SKILLS.forEach(([n,k],i)=>{const v=val('sk',i,k);if(v!=null)sk[n]=v;});editor.skills=sk;}}editor.traits=lines(get('dm-e-traits')).map(l=>{const i=l.indexOf(':');return {name:i<0?l:l.slice(0,i),description:i<0?'':l.slice(i+1).trim()};});editor.resources=Object.entries(pairs(get('dm-e-resources'))).map(([name,max])=>{const old=editor.resources.find(r=>r.name===name);return {...old,id:old?.id||uuid(),name,max};});for(const [key]of GROUPS)editor[key]=editor[key].map((a,i)=>{const p=`dm-a-${key}-${i}`;const rows=(a._rows||[]).map((r,k)=>({qtd:get(`${p}-r${k}-q`)??r.qtd,dado:get(`${p}-r${k}-d`)??r.dado,tipo:get(`${p}-r${k}-t`)??r.tipo}));a._rows=rows;const parts=rowsToParts022(rows);return {...a,name:get(p+'-name')??a.name,kind:get(p+'-kind')??a.kind,attackBonus:get(p+'-hit')??a.attackBonus,formula:get(p+'-formula')??a.formula,damageType:get(p+'-type')??a.damageType,dc:get(p+'-dc')??a.dc,saveAbility:get(p+'-save')??a.saveAbility,maxUses:get(p+'-uses')??a.maxUses,rechargeMin:get(p+'-recharge')??a.rechargeMin,legendaryCost:get(p+'-cost')??a.legendaryCost,description:get(p+'-desc')??a.description,damageParts:parts,_rows:rows,...(parts.length?{formula:parts.map(x=>x.formula).join('+').replace(/\+-/g,'-'),damageType:new Set(parts.map(x=>x.type)).size>1?'misto':parts[0].type}:{})};});}
 function list(){const q=norm(query),lo=minCR===''?-Infinity:parseMonsterCR016(minCR),hi=maxCR===''?Infinity:parseMonsterCR016(maxCR);return items().filter(m=>(filter==='all'||filter==='custom'&&saved.custom.some(x=>x.id===m.id)||filter==='book'&&catalog.some(x=>x.id===m.id))&&(!q||norm([m.name,m.type,m.cr,m.source].join(' ')).includes(q))&&(!typeFilter||m.type===typeFilter)&&(!sizeFilter||m.size===sizeFilter)&&(!reviewFilter||reviewFilter==='pending'&&m.pending||reviewFilter==='provisional'&&m.provisional&&!m.pending||reviewFilter==='verified'&&!m.pending&&!m.provisional)&&(minCR===''&&maxCR===''||parseMonsterCR016(m.cr)>=lo&&parseMonsterCR016(m.cr)<=hi)).sort((a,b)=>{if(q){const ra=norm(a.name)===q?0:norm(a.name).startsWith(q)?1:norm(a.name).includes(q)?2:3,rb=norm(b.name)===q?0:norm(b.name).startsWith(q)?1:norm(b.name).includes(q)?2:3;if(ra!==rb)return ra-rb;}return a.name.localeCompare(b.name,'pt-BR');});}
 function monstersView(){const many=list(),pages=Math.max(1,Math.ceil(many.length/24));pageNumber=Math.min(pageNumber,pages-1);const choices=key=>[...new Set(items().map(m=>m[key]))].sort().map(x=>[x,x]);return `<div class="dm-toolbar dm-filterbar">${field('Buscar criaturas','dm-search',input('dm-search',query,'search','placeholder="Nome, tipo ou ND"'))}${select('dm-filter',[['all','Todas'],['book','Livro'],['custom','Personalizadas']],filter,'Origem')}${select('dm-type',[['','Todos os tipos'],...choices('type')],typeFilter,'Tipo de criatura')}${select('dm-size',[['','Todos os tamanhos'],...choices('size')],sizeFilter,'Tamanho')}${select('dm-review-status',[['','Todos os estados'],['verified','Conferidos / personalizados'],['provisional','Extraídos a conferir'],['pending','Dados incompletos']],reviewFilter,'Conferência dos dados')}${field('ND mínimo','dm-min-cr',input('dm-min-cr',minCR,'text','placeholder="0 ou 1/4"'))}${field('ND máximo','dm-max-cr',input('dm-max-cr',maxCR,'text','placeholder="30"'))}${field('Quantidade a adicionar','dm-amount',input('dm-amount',quantity,'number','min="1" max="50"'))}</div>${tab==='custom'?`<div class="dm-custom-intro"><p><strong>Seus monstros próprios.</strong> Crie uma criatura do zero ou abra um monstro no Catálogo e use <em>Criar cópia editável</em> para adaptá-lo. Eles ficam salvos neste navegador e entram no backup <em>Exportar mestre</em>.</p>${button('+ Criar monstro do zero','create','','primary')}</div>`:''}<p class="hint">${html(info())}</p><div class="between"><b>${many.length} resultado(s)</b><span>Página ${pageNumber+1}/${pages}</span>${button('Limpar filtros','filters-reset','','small ghost')}</div><div class="dm-catalog-grid">${many.slice(pageNumber*24,pageNumber*24+24).map(m=>`<article class="card dm-monster-card">${imgOf(m.id)?`<img class="dm-thumb" src="${imgOf(m.id)}" alt="">`:''}<span class="badge">ND ${html(m.cr)}</span><h3>${html(m.name)}</h3><p>${html(m.size)} · ${html(m.type)}</p><small>${html(m.source)}${m.page?' · p. '+html(m.page):''}</small><div class="dm-review-badge ${m.pending?'pending':m.provisional?'provisional':'verified'}">${m.pending?'Bloco incompleto':m.provisional?'Extraído · conferir no livro':'Conferido / personalizado'}</div><div class="dm-mini-stats">${m.pending?'Dados pendentes de revisão':`CA ${m.ac} · PV ${m.hp} · Inic. ${sgn(m.initiative)}`}</div><div class="dm-card-actions">${button('Ver ficha','view',`data-id="${html(m.id)}"`,'small ghost')}${button('Adicionar','add',`data-id="${html(m.id)}" ${m.pending?'disabled':''}`,'small primary')}</div></article>`).join('')||(tab==='custom'&&!saved.custom.length?'<p>Você ainda não criou nenhum monstro. Use o botão <strong>+ Criar monstro do zero</strong> acima.</p>':'<p>Nenhuma criatura encontrada.</p>')}</div><div class="dm-toolbar">${button('Anterior','page',`data-page="${pageNumber-1}" ${pageNumber?'':'disabled'}`,'small ghost')}${button('Próxima','page',`data-page="${pageNumber+1}" ${pageNumber<pages-1?'':'disabled'}`,'small ghost')}</div>`;}
 const imgOf=id=>{const v=saved.images?.[id];return validImage028(v)?v:'';};let imgTarget='';
 function compressImage(file){return new Promise((ok,fail)=>{if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))return fail(Error('Escolha uma imagem JPG, PNG, WEBP ou GIF.'));if(file.size>15000000)return fail(Error('Imagem acima de 15 MB.'));const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{let side=520,q=0.8,out='';for(let k=0;k<8;k++){const sc=Math.min(1,side/Math.max(im.width,im.height)),w=Math.max(1,Math.round(im.width*sc)),h=Math.max(1,Math.round(im.height*sc)),cv=document.createElement('canvas');cv.width=w;cv.height=h;const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,w,h);cx.drawImage(im,0,0,w,h);out=cv.toDataURL('image/jpeg',q);if(out.length<140000)break;if(q>0.55)q-=0.1;else side=Math.round(side*0.8);}URL.revokeObjectURL(url);if(!validImage028(out))throw Error('Não foi possível converter a imagem.');ok(out);}catch(e){fail(e);}};im.onerror=()=>{URL.revokeObjectURL(url);fail(Error('Não foi possível abrir esta imagem.'));};im.src=url;});}
 function portraitHtml(m){const src=imgOf(m.id),can=!!(src&&canShowImage?.());return `<div class="dm-portrait">${src?`<img src="${src}" alt="Aparência de ${html(m.name)}">`:`<div class="dm-portrait-empty">Sem imagem da aparência</div>`}<div class="dm-portrait-tools">${button(src?'Trocar imagem':'Adicionar imagem','img-pick',`data-id="${html(m.id)}"`,'small'+(src?' ghost':' primary'))}${src?button('Remover','img-remove',`data-id="${html(m.id)}"`,'small ghost'):''}${src&&showImage?button('Mostrar aos jogadores','img-show',`data-id="${html(m.id)}" ${can?'':'disabled title="Abra a Mesa online e tenha jogadores conectados"'}`,'small primary'):''}</div></div>`;}
 function npcView(){const list=saved.npcs||[];let local=[];try{local=npcTools?.siteList?.()||[];}catch{}
  return `<section class="card dm-npc-create"><div><h3>Criar NPC</h3><p class="hint">Abre o criador de ficha padrão (classe, espécie, antecedente, atributos e equipamento). Ao terminar, a ficha vira um NPC aqui.</p></div>${button('+ Criar NPC','npc-create','','primary')}</section><section class="card dm-npc-import"><h3>Importar fichas como NPC</h3><p class="hint">A ficha vira um NPC com CA, PV, atributos, salvaguardas, perícias, iniciativa e os ataques das armas (e o ataque mágico, se conjurar). Depois é só adicionar ao encontro: ele ganha painel, vida e rolagens como os monstros. A ficha original não é alterada.</p><div class="dm-npc-ways"><div><b>Do próprio site</b><p class="hint">Fichas salvas neste navegador.</p>${local.length?`<div class="flex">${select('dm-npc-site',local.map(c=>[c.id,c.name]),'','Ficha do site')}${button('Importar','npc-from-site','','small primary')}${button('Importar todas','npc-from-site-all','','small ghost')}</div>`:'<p class="hint">Nenhuma ficha salva neste navegador.</p>'}</div><div><b>Arquivo JSON</b><p class="hint">Ficha exportada pelo site (uma ficha ou o arquivo “Exportar todas”).</p><label class="btn small primary" for="dm-npc-file">Escolher arquivo JSON</label><input id="dm-npc-file" type="file" accept=".json,application/json" hidden></div></div></section>
  <div class="dm-npc-list">${list.length?list.map(n=>`<article class="card dm-npc-card"><div>${imgOf(n.id)?`<img class="dm-thumb" src="${imgOf(n.id)}" alt="">`:''}<span class="eyebrow">NPC</span><h3>${html(n.name)}</h3><small>${html(n.type)}${n.npcOrigin?' · '+html(n.npcOrigin):''}</small><p class="dm-npc-facts"><span>CA <b>${n.ac}</b></span><span>PV <b>${n.hp}</b></span><span>Inic. <b>${sgn(n.initiative)}</b></span><span>${html(n.speed)}</span></p></div><div class="flex">${button('Ver ficha','view',`data-id="${html(n.id)}"`,'small ghost')}${button('Adicionar ao encontro','add',`data-id="${html(n.id)}"`,'small primary')}${button('Excluir','npc-delete',`data-id="${html(n.id)}"`,'small ghost')}</div></article>`).join(''):'<div class="card empty"><p>Nenhum NPC ainda. Importe uma ficha acima.</p></div>'}</div>`;}
 function addNpcs(arr){saved.npcs=saved.npcs||[];let n=0;for(const raw of arr){if(saved.npcs.length>=300)throw Error('Limite de 300 NPCs.');const m=normalizeMonster(raw,{id:'npc-'+uuid()});m.npc=true;m.npcOrigin=clip(raw.npcOrigin,160);m.importedAt=new Date().toLocaleDateString('pt-BR');saved.npcs.push(m);n++;}tab='npc';refresh();notify(n+' NPC(s) importado(s).');}
 function autoOrAsk(amount,label,heal,iid){const la=iid&&lastAttack[iid];if(!heal&&la&&Date.now()-la.t<600000){delete lastAttack[iid];if(la.hit){const x=targetList().find(y=>y.id===la.tid);if(x){applyAmount(x,amount,false);log(label+' → dano em '+x.name,amount,la.crit?'Ataque crítico':'Ataque acertou');notify('Dano de '+amount+' aplicado em '+x.name+'.');return;}}else{notify('O último ataque em '+la.name+' errou. Escolha um alvo só se houver dano mesmo assim.');}}askTargets(amount,label,heal,iid);}
 function attackDialog(){const pa=pendingAttack,mm=monster(pa.mid),pw=mm?.[pa.list]?.[Number(pa.index)],t=targetList().filter(x=>x.id!=='m:'+pa.instance);return panel('Quem está sendo atacado?',`<div class="dm-dmg-head"><b>${html(mm?actorLabel(mm,pa.instance):'')} · ${html(pw?.name||'Ataque')}</b><span>${pw?'+'+pw.attackBonus+' para acertar':''}</span></div><fieldset class="dm-dmg-targets"><legend>Escolha o alvo</legend>${t.map((x,i)=>`<label class="${x.kind==='pc'?'is-pc':''}"><input type="radio" name="dm-atk" class="dm-atk-target" value="${html(x.id)}" ${i===0?'':''}><span>${html(x.name)}</span><small>${x.kind==='pc'?'jogador':'criatura'} · CA ${html(x.ac)} · ${x.hp??'—'}/${x.maxHp??'—'} PV</small></label>`).join('')}</fieldset><p class="hint">O site compara o resultado com a CA do alvo (20 natural sempre acerta, 1 natural sempre erra). Depois, o botão Dano aplica o dano direto nesse alvo se o ataque acertou.</p>`,button('Sem alvo (só rolar)','atk-none','','ghost')+button('Rolar ataque','atk-confirm','','primary'));}
